using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;

namespace TutoriasWeb
{
    public partial class Home1 : System.Web.UI.Page
    {
        protected void Page_Load(object sender, EventArgs e)
        {
            if (Session["id"] == null)
            {
                Response.Redirect("Login.aspx");
            }

            imgh.ImageUrl = "data:image/jpeg;base64,";
            if (Session["id"].ToString() != "adminsu")
            {
                dsTutoriasTableAdapters.CarreraTableAdapter ta = new dsTutoriasTableAdapters.CarreraTableAdapter();
                dsTutorias.CarreraDataTable dt = ta.GetDataByNombre(Session["carrera"].ToString());
                imgh.ImageUrl = dt[0][2].ToString();
            }
        }

    }
}